"""Generates the sync client (src/inboundr/_client.py) from the async one.

    python scripts/unasync.py          regenerate
    python scripts/unasync.py --check  exit 1 if _client.py is stale (run in CI)

The two clients are the same code apart from async/await, so writing one and
deriving the other keeps them from drifting.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

PKG = Path(__file__).resolve().parent.parent / "src" / "inboundr"
SOURCE = PKG / "_async_client.py"
TARGET = PKG / "_client.py"

HEADER = (
    '"""The sync client. GENERATED by scripts/unasync.py from _async_client.py.\n'
    'Do not edit; change _async_client.py and regenerate."""\n'
)

REPLACEMENTS: list[tuple[str, str]] = [
    (r"\bAsyncIterator\b", "Iterator"),
    (r"\basync def ", "def "),
    (r"\basync for ", "for "),
    (r"\bawait ", ""),
    (r"\bhttpx\.AsyncClient\b", "httpx.Client"),
    (r"\.aclose\(\)", ".close()"),
    (r"\b__aenter__\b", "__enter__"),
    (r"\b__aexit__\b", "__exit__"),
    (r"\b_AsyncResource\b", "_Resource"),
    (r"\bAsync([A-Z]\w*)", r"\1"),
]


def transform(source: str) -> str:
    # Replace the module docstring, then rewrite the body.
    body = re.sub(r'\A""".*?"""\n', "", source, count=1, flags=re.S)
    for pattern, replacement in REPLACEMENTS:
        body = re.sub(pattern, replacement, body)
    return HEADER + body


def main() -> int:
    generated = transform(SOURCE.read_text())
    if "--check" in sys.argv:
        if not TARGET.exists() or TARGET.read_text() != generated:
            print("src/inboundr/_client.py is stale. Run `python scripts/unasync.py`.", file=sys.stderr)
            return 1
        print("unasync: _client.py is up to date")
        return 0
    TARGET.write_text(generated)
    print("unasync: wrote src/inboundr/_client.py")
    return 0


if __name__ == "__main__":
    sys.exit(main())
